import 'dart:math' as math;

import 'package:flutter/material.dart';

import '../theme/app_theme.dart';

/// The CoRoute logo (v3.58): a rider's helmet as the "o" of CoRoute.
///
/// Drawn in code so it is sharp at every size and follows light/dark theme. Same geometry as the
/// SVG masters in docs/brand/svg (generated by tool/brand/build_brand.py); see
/// docs/brand/BRAND_GUIDE_v3.58.md for colours, clear space and minimum sizes.
class CoRouteBrand {
  CoRouteBrand._();

  static const Color teal = Color(0xFF2B7A8C);
  static const Color tealLight = Color(0xFF5FB3C4);
  static const Color amber = Color(0xFFD9822B);
  static const Color ink = Color(0xFF15181C);
  static const Color paper = Color(0xFFF6F4F0);

  /// Helmet bounds inside the 100 x 100 design box.
  static const Rect helmetBounds = Rect.fromLTRB(10, 14, 92, 82);

  static Path shell() => Path()
    ..moveTo(10, 64)
    ..cubicTo(10, 36, 30, 14, 56, 14)
    ..cubicTo(78, 14, 92, 30, 92, 50)
    ..lineTo(92, 68)
    ..cubicTo(92, 76, 86, 82, 78, 82)
    ..lineTo(24, 82)
    ..cubicTo(16, 82, 10, 76, 10, 68)
    ..close();

  /// The visor: the road ahead.
  static Path visor() => Path()
    ..moveTo(28, 58)
    ..cubicTo(46, 58, 58, 46, 92, 42)
    ..lineTo(92, 58)
    ..cubicTo(72, 60, 60, 68, 44, 70)
    ..close();

  /// The amber light: the lead rider / the sun on the road.
  static const Offset sunCentre = Offset(76, 30);
  static const double sunRadius = 7;
}

/// Paints the helmet scaled to fill the canvas width (height = width * 68 / 82).
class _HelmetPainter extends CustomPainter {
  final Color shell;
  final Color visor;
  final Color sun;

  const _HelmetPainter({required this.shell, required this.visor, required this.sun});

  @override
  void paint(Canvas canvas, Size size) {
    const b = CoRouteBrand.helmetBounds;
    final s = size.width / b.width;
    canvas.save();
    canvas.scale(s);
    canvas.translate(-b.left, -b.top);
    canvas.drawPath(CoRouteBrand.shell(), Paint()..color = shell..isAntiAlias = true);
    canvas.drawPath(CoRouteBrand.visor(), Paint()..color = visor..isAntiAlias = true);
    canvas.drawCircle(CoRouteBrand.sunCentre, CoRouteBrand.sunRadius, Paint()..color = sun..isAntiAlias = true);
    canvas.restore();
  }

  @override
  bool shouldRepaint(_HelmetPainter old) => old.shell != shell || old.visor != visor || old.sun != sun;
}

/// The helmet on its own. [width] sets the size; the height follows the helmet's proportions.
class CoRouteHelmet extends StatelessWidget {
  final double width;
  final Color? shellColor;
  final Color visorColor;
  final Color sunColor;

  const CoRouteHelmet({
    super.key,
    required this.width,
    this.shellColor,
    this.visorColor = CoRouteBrand.tealLight,
    this.sunColor = CoRouteBrand.amber,
  });

  static double heightFor(double width) =>
      width * CoRouteBrand.helmetBounds.height / CoRouteBrand.helmetBounds.width;

  @override
  Widget build(BuildContext context) {
    final shell = shellColor ?? (AppTheme.isLight ? CoRouteBrand.ink : CoRouteBrand.paper);
    return SizedBox(
      width: width,
      height: heightFor(width),
      child: CustomPaint(painter: _HelmetPainter(shell: shell, visor: visorColor, sun: sunColor)),
    );
  }
}

/// The app icon: brand teal rounded square with the light helmet (same art as the launcher icon).
class CoRouteAppIcon extends StatelessWidget {
  final double size;
  final String? semanticLabel;

  const CoRouteAppIcon({super.key, this.size = 72, this.semanticLabel = 'CoRoute'});

  @override
  Widget build(BuildContext context) {
    // The helmet's diagonal fills 78 % of the icon, as in the launcher and Play icons.
    const b = CoRouteBrand.helmetBounds;
    final scale = size * 0.78 / math.sqrt(b.width * b.width + b.height * b.height);
    final icon = Container(
      width: size,
      height: size,
      decoration: BoxDecoration(color: CoRouteBrand.teal, borderRadius: BorderRadius.circular(size * 0.225)),
      alignment: Alignment.center,
      child: Padding(
        padding: EdgeInsets.only(top: size * 0.02),
        child: CoRouteHelmet(
          width: b.width * scale,
          shellColor: CoRouteBrand.paper,
          visorColor: CoRouteBrand.ink,
          sunColor: CoRouteBrand.amber,
        ),
      ),
    );
    final label = semanticLabel;
    return label == null ? ExcludeSemantics(child: icon) : Semantics(image: true, label: label, child: ExcludeSemantics(child: icon));
  }
}

/// The wordmark: "C", the helmet as the "o", "Route". Manrope ExtraBold, tight tracking.
/// Text colour follows the theme (ink on light, paper on dark) unless [color] is given.
class CoRouteWordmark extends StatelessWidget {
  final double fontSize;
  final Color? color;

  const CoRouteWordmark({super.key, this.fontSize = 28, this.color});

  @override
  Widget build(BuildContext context) {
    final c = color ?? (AppTheme.isLight ? CoRouteBrand.ink : CoRouteBrand.paper);
    final style = TextStyle(
      fontFamily: AppTheme.fontFamily,
      fontSize: fontSize,
      fontWeight: FontWeight.w800,
      letterSpacing: -0.028 * fontSize,
      height: 1.1,
      color: c,
    );
    // Manrope's x-height is 0.54 em; the helmet is 1.04 x-height tall, bottom on the baseline.
    final helmetH = fontSize * 0.54 * 1.04;
    final helmetW = helmetH * CoRouteBrand.helmetBounds.width / CoRouteBrand.helmetBounds.height;
    return Semantics(
      label: 'CoRoute',
      header: true,
      child: ExcludeSemantics(
        child: Text.rich(
          TextSpan(
            style: style,
            children: [
              const TextSpan(text: 'C'),
              WidgetSpan(
                alignment: PlaceholderAlignment.middle,
                child: Padding(
                  padding: EdgeInsets.symmetric(horizontal: fontSize * 0.03),
                  child: CoRouteHelmet(width: helmetW, shellColor: c),
                ),
              ),
              const TextSpan(text: 'Route'),
            ],
          ),
          maxLines: 1,
          softWrap: false,
          textScaler: TextScaler.noScaling,
        ),
      ),
    );
  }
}
